declare module 'fastify' {
  interface FastifyRequest {
    currentUser?: AuthenticatedUser;
    currentSession?: SessionRecord;
    apiKeyAuth?: { id: string; scopes: ApiKeyScope[] };

    /* A workspace-app object-storage grant (non-user principal scoped to one project). */
    objectStorageGrant?: { projectId: string; organizationId: string; userId?: string; workspaceId?: string };
    rawBody?: string;
    observability?: { startedAt: number; correlationId: string };
    observabilityMetrics?: {
      increment: (name: string, labels?: Record<string, string | number | boolean | undefined>, value?: number) => void;
    };

    /** Internal-only durable rollback executor; never serialized to clients. */
    rollbackOperation?: {
      operationId: string;
      ownerToken: string;
      fencingToken: number;
      leaseManager: RollbackOperationLeaseManager;
    };
  }
}

/**
 * The workspace-pod static-build seam (#26 sub-part 2). Returns `{ handled: false }`
 * only when the project's workspace pod could not be reached even after a
 * provision + health-poll — in which case the deploy fails cleanly; the build is
 * NEVER retried in-process on the api pod.
 */
export type WorkspacePodStaticBuild = (
  request: any,
  project: { id: string; organizationId: string },
  body: {
    buildCommand: string;
    outputDirectory: string;
    timeoutSeconds: number;
    artifactSizeLimitMb?: number;
    workspaceId?: string;
  },
  deploymentId: string,
  progress?: { onLog?: (log: StaticBuildLog) => void; onPhase?: (phase: string) => void },
) => Promise<{ handled: false } | { handled: true; result: RunStaticBuildResult; tempDir: string }>;

export interface ApiAppOptions {
  store?: ApiStore;
  agentMemory?: AgentMemoryService;
  mcpMarketplace?: McpMarketplaceService;

  /**
   * Test-only storage seam. Production rejects injected adapters because an
   * implementation cannot be wrapped safely around its own check-to-write
   * window; the built-in LocalProjectStorage shares its distributed lock with
   * account-purge erasure.
   */
  projectStorage?: ProjectStorage;

  /** Production defaults to CNPG; injected only for deterministic migration tests. */
  databaseProvisioner?: DatabaseProvisioner;

  /** Deterministic test seam; production reads set-once authority from DatabaseInstance. */
  databasePhysicalAuthorityResolver?: (
    projectId: string,
    environment: 'development' | 'production',
  ) => Promise<DatabasePhysicalAuthority | undefined>;

  /** Production defaults to the real transactional PostgreSQL applicator. */
  migrationApplier?: SqlApplier;

  /** Read-only complete-ledger inspection seam for deterministic rollback tests. */
  migrationLedgerInspector?: typeof inspectExactPostgresMigrationLedger;

  /**
   * Storage for cron-scheduled tasks. Defaults to Postgres when the store is
   * Prisma-backed; tests inject an in-memory repository so the executor can be
   * driven without a database.
   */
  scheduledTaskRepository?: ScheduledTaskRepository;

  /** Override the per-project object storage backend (tests inject a fake). */
  objectStorage?: ObjectStorage;

  /** Test seam for account purge; production uses real GCS + workspace-manager. */
  accountStoragePurger?: (
    inventory: PurgeStorageInventory,
    userId: string,
    lease: PurgeLeaseContext,
  ) => Promise<{ classes: PurgeClassReport[]; verified: boolean }>;

  /** Test seam for the fail-closed external billing step of account purge. */
  accountPurgeBillingCanceler?: (
    externalSubscriptionId: string,
    idempotencyKey: string,
  ) => Promise<{ canceled: boolean; providerStatus?: string }>;

  /** Test seam for the workspace-manager stale-fence reconciliation call. */
  accountPurgeWorkspaceReconciler?: (
    take: number,
  ) => Promise<{ scanned: number; reconciled: number; workspaceIds: string[] }>;

  /** Deterministic test seam; production uses the fenced workspace-manager control plane. */
  projectWorkspaceDeletion?: typeof projectWorkspaceDeletionRequest;

  /** Deterministic test seam; production binds CNPG/GCS/SQL to the deletion lease. */
  projectDatabaseErasureServiceFactory?: (
    lease: ObjectStorageOperationLease,
    expectedOrganizationId: string,
  ) => Pick<ProjectDatabaseErasureService, 'preflight' | 'purge' | 'verify'>;

  /** Injectable for tests; defaults to an env-configured (inert-unless-set) capturer. */
  thumbnailCapturer?: ThumbnailCapturer;
  gitProvider?: GitProvider;
  emailProvider?: EmailProvider;
  jwtSecret?: string;
  allowedOrigins?: string[];
  isProduction?: boolean;
  aiGatewayUrl?: string;
  loggerStream?: { write(line: string): void };

  /**
   * Override the static build orchestrator. Production uses the default
   * exported from `./deployments`, which spawns `npm install` + the user's
   * build command on the host. Tests inject a deterministic implementation.
   */
  staticBuildRunner?: typeof runStaticBuild;

  /** Live OCI/Artifact Registry promotion seam; production resolves ADC/WI from env. */
  serverImagePromotionRuntime?: ServerImagePromotionRuntime;

  /** Exact registry inventory/delete seam; production resolves ADC/WI. */
  projectRegistryErasureProvider?: ProjectRegistryErasureProvider;

  /**
   * Override the durable deploy-build enqueue path. Production uses the default
   * BullMQ enqueue exported from `./deploy-queue`; tests can inject a spy (the
   * sync/injected-runner path never enqueues, so this is only exercised by the
   * async workspace-pod path).
   */
  enqueueDeployJob?: typeof enqueueDeployBuildJob;

  /**
   * Force the workspace-pod build on/off, decoupled from `staticBuildRunner`
   * injection. Production leaves this undefined (workspace-pod build is the
   * default whenever no runner is injected). Tests set it `true` to exercise the
   * real "build only in the workspace pod, never in the api pod" path while still
   * injecting a `staticBuildRunner` spy to PROVE the in-api build is never called.
   */
  useWorkspacePodBuild?: boolean;

  /**
   * Override the workspace-pod build seam. Production uses the real closure that
   * streams the build over the workspace-agent WS; tests inject a deterministic
   * implementation so the deploy flow can be driven without a live pod.
   */
  buildStaticInWorkspacePod?: WorkspacePodStaticBuild;

  /**
   * Override the platform Prometheus registry. Production/dev create a fresh one;
   * tests inject a shared registry so they can record known metrics and then
   * assert the `/admin/platform-metrics` JSON reflects them.
   */
  metricsRegistry?: ReturnType<typeof createPrometheusRegistry>;

  /** Injectable CloudTenant control plane; production builds it on Prisma + ADC/WI. */
  cloudGovernanceService?: CloudGovernanceService;
}

function createDefaultStore() {
  if (process.env.DATABASE_URL) {
    return new PrismaApiStore();
  }

  throw new Error(appPublicEnglish('INTERNAL_DATABASE_URL_REQUIRED'));
}

function createDefaultAgentMemory(store: ApiStore) {
  if (!process.env.DATABASE_URL || !process.env.OPENAI_API_KEY) {
    return undefined;
  }

  if (store instanceof PrismaApiStore) {
    return createPostgresAgentMemoryService(store.prisma);
  }

  return undefined;
}

