function parse<T>(schema: ZodSchema<T>, value: unknown): T {
  return schema.parse(value);
}

async function currentProjectManifest(
  store: ApiStore,
  project: Pick<ProjectRecord, 'id' | 'organizationId'>,
): Promise<{ manifest: ProjectManifest; digest: string }> {
  let revision = await store.getLatestProjectManifest(project.id);

  /*
   * Existing projects predate migration 0092. Materialize their conservative
   * one-artifact manifest on first read under the store's cross-replica lock;
   * an exact concurrent insert is idempotent.
   */
  if (!revision) {
    const manifest = createDefaultProjectManifest(project.id);
    revision = await store.createProjectManifestRevision({
      projectId: project.id,
      expectedOrganizationId: project.organizationId,
      schemaVersion: manifest.schemaVersion,
      manifestVersion: manifest.manifestVersion,
      digest: projectManifestDigest(manifest),
      manifest,
    });
  }

  return {
    manifest: verifyStoredProjectManifestRevision(revision, project.id),
    digest: revision.digest,
  };
}

async function deploymentProjectManifestIsCurrent(
  store: ApiStore,
  project: Pick<ProjectRecord, 'id' | 'organizationId'>,
  deployment: Pick<DeploymentRecord, 'metadata'>,
): Promise<boolean> {
  const boundDigest = (deployment.metadata as Record<string, unknown> | undefined)?.projectManifestDigest;

  /* Pre-0092 rows have no binding and retain their legacy compatibility path. */
  if (typeof boundDigest !== 'string') {
    return true;
  }

  if (!PROJECT_MANIFEST_DIGEST_PATTERN.test(boundDigest)) {
    return false;
  }

  return (await currentProjectManifest(store, project)).digest === boundDigest;
}

function aiTranscriptMessageId(conversationId: string, clientId: string) {
  return `aimsg_${createHash('sha256').update(`${conversationId}:${clientId}`).digest('hex').slice(0, 32)}`;
}

async function pathExistsAsync(targetPath: string) {
  try {
    await stat(targetPath);
    return true;
  } catch {
    return false;
  }
}

async function readableFileOrUndefined(targetPath: string) {
  try {
    const info = await lstat(targetPath);
    return info.isFile() ? targetPath : undefined;
  } catch {
    return undefined;
  }
}

