  app.put('/orgs/:orgId/sso/enforcement', async (request) => {
    const { orgId } = parse(orgParams, request.params);
    const body = parse(ssoEnforcementSchema, request.body);
    await requireOrg(request, store, orgId, 'security:manage');
    await requireRecentAdminReauth(request);

    const current = await store.getEnterpriseSettings(orgId);

    /*
     * Only (re)start the grace clock when turning enforcement ON from an OFF
     * state — re-saving while already enforced must not reset an in-flight grace
     * window. Turning it off clears the timestamp (null).
     */
    let ssoEnforcedAt: string | null;

    if (body.enforced) {
      ssoEnforcedAt = current.ssoEnforced && current.ssoEnforcedAt ? current.ssoEnforcedAt : new Date().toISOString();
    } else {
      ssoEnforcedAt = null;
    }

    const settings = await store.updateEnterpriseSettings({
      organizationId: orgId,
      ssoEnforced: body.enforced,
      ssoEnforcedAt,
    });
    await audit(request, store, {
      organizationId: orgId,
      action: 'sso.enforcement.update',
      resourceType: 'enterpriseSettings',
      resourceId: orgId,
    });

    return { enforcement: buildSsoEnforcementView(settings) };
  });
  app.post('/orgs/:orgId/scim/tokens', async (request, reply) => {
    const { orgId } = parse(orgParams, request.params);
    const body = parse(scimTokenSchema, request.body);
    await requireOrg(request, store, orgId, 'scim:manage');
    await requireRecentAdminReauth(request);

    const token = createOpaqueToken('scim');
    const scimToken = await store.createScimToken({ organizationId: orgId, name: body.name, token });
    await audit(request, store, {
      organizationId: orgId,
      action: 'scim.token.create',
      resourceType: 'scimToken',
      resourceId: scimToken.id,
    });

    return reply
      .code(201)
      .send({ token, scimToken: { id: scimToken.id, name: scimToken.name, createdAt: scimToken.createdAt } });
  });
  app.get('/orgs/:orgId/scim/tokens', async (request) => {
    const { orgId } = parse(orgParams, request.params);
    await requireOrg(request, store, orgId, 'scim:manage');

    const tokens = await store.listScimTokens(orgId);

    return {
      scimTokens: tokens.map((token) => {
        const expiresAt = new Date(
          new Date(token.createdAt).getTime() + scimTokenMaxAgeDays * 24 * 60 * 60 * 1000,
        ).toISOString();
        return {
          id: token.id,
          name: token.name,
          createdAt: token.createdAt,
          lastUsedAt: token.lastUsedAt,
          expiresAt,
          expired: isScimTokenExpired(token),
        };
      }),
    };
  });
  app.delete('/orgs/:orgId/scim/tokens/:tokenId', async (request, reply) => {
    const params = parse(z.object({ orgId: z.string().min(1), tokenId: z.string().min(1) }), request.params);
    await requireOrg(request, store, params.orgId, 'scim:manage');
    await requireRecentAdminReauth(request);

    /*
     * Confirm the token belongs to this org BEFORE the (unscoped) delete, so an
     * admin of one org cannot delete another tenant's SCIM token by id.
     */
    const ownsScimToken = (await store.listScimTokens(params.orgId)).some((token) => token.id === params.tokenId);

    if (!ownsScimToken) {
      return reply.code(404).send({ error: appPublicEnglish('SCIM_TOKEN_NOT_FOUND'), code: 'SCIM_TOKEN_NOT_FOUND' });
    }

    const revoked = await store.revokeScimToken(params.tokenId);

    if (!revoked || revoked.organizationId !== params.orgId) {
      return reply.code(404).send({ error: appPublicEnglish('SCIM_TOKEN_NOT_FOUND'), code: 'SCIM_TOKEN_NOT_FOUND' });
    }

    await audit(request, store, {
      organizationId: params.orgId,
      action: 'scim.token.revoke',
      resourceType: 'scimToken',
      resourceId: revoked.id,
    });

    return reply.code(204).send();
  });
  app.post('/orgs/:orgId/scim/tokens/:tokenId/rotate', async (request, reply) => {
    const params = parse(z.object({ orgId: z.string().min(1), tokenId: z.string().min(1) }), request.params);
    await requireOrg(request, store, params.orgId, 'scim:manage');
    await requireRecentAdminReauth(request);

    /*
     * Confirm the token belongs to this org BEFORE the (unscoped) delete, so an
     * admin of one org cannot delete another tenant's SCIM token by id.
     */
    const existingRotateToken = (await store.listScimTokens(params.orgId)).find((token) => token.id === params.tokenId);

    if (!existingRotateToken) {
      return reply.code(404).send({ error: appPublicEnglish('SCIM_TOKEN_NOT_FOUND'), code: 'SCIM_TOKEN_NOT_FOUND' });
    }

    /*
     * F16 — 24h dual-valid rotation: mint the new bearer IN PLACE on the SAME token
     * id (previous hash retained + rotatedAt stamped) instead of revoke-then-recreate.
     * The OLD bearer keeps authenticating for 24h (store.findScimToken), so an IdP can
     * swap the secret with zero provisioning downtime.
     */
    const token = createOpaqueToken('scim');
    const scimToken = await store.rotateScimToken(params.tokenId, token);

    if (!scimToken || scimToken.organizationId !== params.orgId) {
      return reply.code(404).send({ error: appPublicEnglish('SCIM_TOKEN_NOT_FOUND'), code: 'SCIM_TOKEN_NOT_FOUND' });
    }

    await audit(request, store, {
      organizationId: params.orgId,
      action: 'scim.token.rotate',
      resourceType: 'scimToken',
      resourceId: scimToken.id,
      metadata: { dualValidHours: 24 },
    });

    return reply
      .code(201)
      .send({ token, scimToken: { id: scimToken.id, name: scimToken.name, createdAt: scimToken.createdAt } });
  });
