  app.delete('/projects/:projectId/collaboration/presence/:sessionId', async (request, reply) => {
    const project = await requireProject(
      request,
      store,
      parse(projectParams, request.params).projectId,
      'projects:read',
    );

    const sessionId = z.object({ sessionId: z.string().min(1) }).parse(request.params).sessionId;

    /*
     * Presence eviction must be scoped to the caller: 'projects:read' is held by
     * viewers too, so without an ownership check any viewer could kick every
     * other collaborator's live session. Allow removing your own session always;
     * removing someone else's requires a non-read-only (editor/admin) role.
     */
    const target = (await store.listCollaborationPresence(project.id)).find((p) => p.sessionId === sessionId);

    if (target && target.userId !== request.currentUser!.id) {
      /*
       * Removing someone else's session requires write capability. Resolve it
       * through requireProject('projects:write') rather than projectCollaborationRole
       * alone — the latter only sees explicit ProjectCollaborator rows, so org
       * owners/admins (who reach the project via org membership, not an explicit
       * collaborator row) were wrongly 403'd and couldn't moderate stale sessions.
       */
      const canManage = await requireProject(request, store, project.id, 'projects:write')
        .then(() => true)
        .catch(() => false);

      if (!canManage) {
        return reply
          .code(403)
          .send({ error: appPublicEnglish('COLLABORATOR_PRESENCE_EVICTION_FORBIDDEN'), code: 'PRESENCE_FORBIDDEN' });
      }
    }

    const removed = await store.removeCollaborationPresence({
      projectId: project.id,
      expectedOrganizationId: project.organizationId,
      sessionId,
    });
    collaborationBroker.publish(
      { projectId: project.id, organizationId: project.organizationId },
      { type: 'presence.leave', sessionId },
    );

    return { removed };
  });
