  /*
   * Admin credit adjustment: credit (positive) or debit (negative) an org's
   * wallet by an arbitrary amount. Appends an ADJUSTMENT ledger entry (the
   * audit trail) and updates the materialized balance atomically via the same
   * recordCreditEntry path grants/usage use. Platform-admin + recent re-auth gated.
   */
  app.post('/admin/wallets/:organizationId/adjust', async (request) => {
    await requirePlatformAdmin(request);
    await requireRecentAdminReauth(request);

    const { organizationId } = parse(z.object({ organizationId: z.string().min(1) }), request.params);

    const body = parse(
      z.object({
        deltaCents: z
          .number()
          .int()
          .refine((value) => value !== 0, { message: appPublicEnglish('WALLET_DELTA_NONZERO') }),

        /*
         * Optional at the schema layer so both a missing AND a whitespace-only
         * reason fall through to the explicit check below, which rejects with the
         * specific WALLET_ADJUST_REASON_REQUIRED code (not the generic zod 400).
         */
        reason: z.string().max(500).optional(),
      }),
      request.body ?? {},
    );

    /*
     * F20: a reason is MANDATORY on every wallet adjustment — it is the human
     * "why" persisted alongside the signed ADJUSTMENT ledger entry (the audit
     * trail the movement-history table renders). Trim first so a whitespace-only
     * reason ("   ") is rejected too, and store the trimmed value.
     */
    const reason = (body.reason ?? '').trim();

    if (!reason) {
      throw Object.assign(new Error(appPublicEnglish('WALLET_REASON_REQUIRED')), {
        statusCode: 400,
        code: 'WALLET_ADJUST_REASON_REQUIRED',
      });
    }

    const { entry, balanceCents } = await store.recordCreditEntry({
      organizationId,
      deltaCents: body.deltaCents,
      kind: 'ADJUSTMENT',
      reason,
    });

    await audit(request, store, {
      organizationId,
      action: 'admin.wallet.adjust',
      resourceType: 'wallet',
      resourceId: organizationId,
      metadata: { deltaCents: body.deltaCents, reason, balanceCents },
    });

    return { wallet: { organizationId, balanceCents }, entry };
  });

  app.get('/admin/checkpoints', async (request) => {
    await requirePlatformAdmin(request);
    return { checkpoints: await store.listAdminAgentCheckpoints({ take: 200 }) };
  });

  /*
   * F21: agent-checkpoint storage — per-org footprint (row count + token/credit
   * totals) + the retention rule (`checkpoints.retentionDays` system setting,
   * default 90) and a dry-run purge estimate (terminal checkpoints older than it).
   */
  app.get('/admin/checkpoints/storage', async (request) => {
    await requirePlatformAdmin(request);

    const query = parse(
      z.object({ olderThanDays: z.coerce.number().int().positive().optional() }),
      request.query ?? {},
    );

    const settings = await store.listSystemSettings();
    const settingDays = Number(settings.find((setting) => setting.key === 'checkpoints.retentionDays')?.value);

    const retentionDays = query.olderThanDays ?? (Number.isFinite(settingDays) && settingDays > 0 ? settingDays : 90);

    const cutoff = new Date(Date.now() - retentionDays * 86_400_000).toISOString();

    const byOrg = await store.summarizeAgentCheckpoints();
    const purgeEstimate = (await store.purgeAgentCheckpoints({ before: cutoff, dryRun: true })).count;

    return {
      retentionDays,
      cutoff,
      totalCheckpoints: byOrg.reduce((sum, entry) => sum + entry.checkpoints, 0),
      totalCreditCents: byOrg.reduce((sum, entry) => sum + entry.creditCents, 0),
      byOrg,
      purgeEstimate,
    };
  });

  /*
   * F21: manual purge — removes terminal (COMPLETED/FAILED) checkpoints older than
   * `olderThanDays`. This deletes settled billing checkpoints, so it is platform-admin
   * + recent re-auth gated and written to AdminAuditLog. The panel shows the estimate
   * before this runs.
   */
  app.post('/admin/checkpoints/purge', async (request) => {
    await requirePlatformAdmin(request);
    await requireRecentAdminReauth(request);

    const body = parse(z.object({ olderThanDays: z.coerce.number().int().positive() }), request.body ?? {});
    const cutoff = new Date(Date.now() - body.olderThanDays * 86_400_000).toISOString();
    const { count } = await store.purgeAgentCheckpoints({ before: cutoff, dryRun: false });
    await recordAdminAction(request, store, {
      action: 'admin.checkpoints.purge',
      metadata: { olderThanDays: body.olderThanDays, cutoff, deleted: count },
    });

    return { deleted: count, cutoff };
  });

  app.get('/admin/stripe-health', async (request) => {
    await requirePlatformAdmin(request);

    const locale = transactionalLocaleForRequest(request);

    if (!stripeClient) {
      return {
        configured: false,
        ok: false,
        detailCode: 'STRIPE_NOT_CONFIGURED',
        detail: appPublicCopy('STRIPE_HEALTH_NOT_CONFIGURED', locale),
      };
    }

    const result = await stripeClient.ping();

    if (!result.ok) {
      request.log.warn({ stripeError: redactSecretString(result.error ?? '') }, 'Stripe health check failed');
    }

    return {
      configured: true,
      ok: result.ok,
      livemode: result.livemode ?? null,
      detailCode: result.ok ? (result.livemode ? 'STRIPE_LIVE_KEY_OK' : 'STRIPE_TEST_KEY_OK') : 'STRIPE_UNREACHABLE',
      detail: result.ok
        ? appPublicCopy(result.livemode ? 'STRIPE_HEALTH_LIVE_KEY_OK' : 'STRIPE_HEALTH_TEST_KEY_OK', locale)
        : appPublicCopy('STRIPE_HEALTH_REQUEST_FAILED', locale),
    };
  });

